{% stylesheet %}
.card{COLOR:red;margin:0 AUTO!important;transition:opacity .3s ease,transform .3s ease;background:URL(a.png)}
.card:HOVER,.card>.title+p{width:calc(100% - 2*var(--gap,10px))}


@media (min-width:750px) and (max-width:990px){.card{display:none}}
/* a comment */
.a{&:hover{color:#FFF}}
{% endstylesheet %}

expected:
{% stylesheet %}
  .card {
    color: red;
    margin: 0 AUTO !important;
    transition:
      opacity 0.3s ease,
      transform 0.3s ease;
    background: URL(a.png);
  }
  .card:hover,
  .card > .title + p {
    width: calc(100% - 2 * var(--gap, 10px));
  }

  @media (min-width: 750px) and (max-width: 990px) {
    .card {
      display: none;
    }
  }
  /* a comment */
  .a {
    &:hover {
      color: #fff;
    }
  }
{% endstylesheet %}

